--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,35 @@
+import { AppError } from "../errors.js";
+import { isDate } from "../dates.js";
+import { parseCsv } from "./csv.js";
+import { importSales } from "../domain/sales.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+
+/** Parses and imports a whole sales CSV, with physical row numbers on errors. */
+export function importSalesCsv(store, text) {
+  const lines = text.split(/\r?\n/);
+  const headerIndex = lines.findIndex((line) => line.trim());
+  const header = parseCsv(lines[headerIndex] ?? "")[0] ?? [];
+  const keys = header.map((cell) => cell.trim());
+  if (keys.length !== HEADER.length || HEADER.some((key) => !keys.includes(key)))
+    throw new AppError("sales_row", { row: 1, reason: "expected columns ticket,soldAt,dishId,qty" });
+  const rows = [];
+  for (let index = headerIndex + 1; index < lines.length; index++) {
+    const line = lines[index];
+    if (!line.trim()) continue;
+    const fail = (reason) => { throw new AppError("sales_row", { row: index + 1, reason }); };
+    if (!/^(?:"(?:[^"]|"")*"|[^",]*)(?:,(?:"(?:[^"]|"")*"|[^",]*))*$/.test(line)) fail("invalid CSV");
+    const cells = parseCsv(line)[0];
+    if (cells.length !== keys.length) fail("wrong number of columns");
+    const row = Object.fromEntries(keys.map((key, i) => [key, cells[i].trim()]));
+    if (!row.ticket) fail("ticket is required");
+    if (!/^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|[+-]\d{2}:\d{2})$/.test(row.soldAt)
+      || !Number.isFinite(Date.parse(row.soldAt)) || !isDate(row.soldAt.slice(0, 10))) fail("soldAt must be an ISO instant");
+    const dishId = Number(row.dishId);
+    const qty = Number(row.qty);
+    if (!Number.isSafeInteger(dishId) || dishId < 1) fail("invalid dishId");
+    if (!Number.isSafeInteger(qty) || qty < 1) fail("qty must be a positive whole number");
+    rows.push({ ticket: row.ticket, soldAt: new Date(row.soldAt).toISOString(), dishId, qty, row: index + 1 });
+  }
+  return importSales(store, rows);
+}
